// Natija aniq bo'lishi uchun vaqtni tashqaridan beramiz (haqiqiy kodda: Date.now)
function throttle<A extends unknown[]>(fn: (...args: A) => void, ms: number, now: () => number = Date.now) {
    let last = -Infinity
    return (...args: A) => {
        const t = now()
        if (t - last >= ms) { last = t; fn(...args) }
    }
}

