async function waitFor(condition: () => boolean, intervalMs = 10, maxTries = 20): Promise<void> {
    for (let attempt = 1; attempt <= maxTries; attempt++) {
        if (condition()) return
        await sleep(intervalMs)
    }
    throw new Error("shart vaqtida bajarilmadi")
}

