type NodeCallback<T> = (error: Error | null, result?: T) => void

function toPromise<T>(call: (done: NodeCallback<T>) => void): Promise<T> {
    return new Promise<T>((resolve, reject) => {
        call((error, result) => (error ? reject(error) : resolve(result as T)))
    })
}

