class Semaphore {
    private waiting: Array<() => void> = []
    private free: number

    constructor(limit: number) { this.free = limit }

    async acquire(): Promise<void> {
        if (this.free > 0) { this.free--; return }
        await new Promise<void>(resolve => this.waiting.push(resolve))   // navbatda kutamiz
    }

    release(): void {
        const next = this.waiting.shift()
        if (next) next()              // bo'sh joy keyingi kutayotganga o'tadi
        else this.free++
    }
}

const semaphore = new Semaphore(2)
let active = 0
let maxActive = 0

async function work(id: number): Promise<number> {
    await semaphore.acquire()
    try {
        active++
        maxActive = Math.max(maxActive, active)
        await new Promise(resolve => setTimeout(resolve, 10))
        return id * 10
    } finally {
        active--
        semaphore.release()
    }
}

