type ApiResult<T> =
    | { status: "ok"; data: T }
    | { status: "notFound" }
    | { status: "error"; message: string }

function handleStatus<T>(code: number, data: T): ApiResult<T> {
    if (code >= 200 && code < 300) return { status: "ok", data }
    if (code === 404) return { status: "notFound" }
    return { status: "error", message: `HTTP ${code}` }
}

function render<T>(result: ApiResult<T>): string {
    switch (result.status) {
        case "ok": return `Ma'lumot: ${JSON.stringify(result.data)}`
        case "notFound": return "Topilmadi"
        case "error": return `Xato: ${result.message}`
