type Shape =
    | { type: "circle"; radius: number }
    | { type: "rect"; width: number; height: number }

function parseShape(raw: unknown): Shape {
    if (typeof raw !== "object" || raw === null || !("type" in raw)) throw new TypeError("type maydoni yo'q")
    const v = raw as Record<string, unknown>
    switch (v.type) {
        case "circle":
            if (typeof v.radius !== "number") throw new TypeError("radius son bo'lishi kerak")
            return { type: "circle", radius: v.radius }
        case "rect":
            if (typeof v.width !== "number" || typeof v.height !== "number") {
                throw new TypeError("width va height son bo'lishi kerak")
            }
            return { type: "rect", width: v.width, height: v.height }
        default:
            throw new TypeError(`noma'lum shakl: ${String(v.type)}`)
    }
}

