type Parser<T> = (raw: unknown) => T

const str: Parser<string> = raw => {
    if (typeof raw !== "string") throw new TypeError(`matn kutilgan, ${typeof raw} keldi`)
    return raw
}

const num: Parser<number> = raw => {
    if (typeof raw !== "number") throw new TypeError(`son kutilgan, ${typeof raw} keldi`)
    return raw
}

function arr<T>(item: Parser<T>): Parser<T[]> {
    return raw => {
        if (!Array.isArray(raw)) throw new TypeError("massiv kutilgan")
        return raw.map(element => item(element))
    }
}

function obj<S extends Record<string, Parser<unknown>>>(shape: S): Parser<{ [K in keyof S]: ReturnType<S[K]> }> {
    return raw => {
        if (typeof raw !== "object" || raw === null) throw new TypeError("obyekt kutilgan")
        const result: Record<string, unknown> = {}
        for (const key of Object.keys(shape)) {
            try {
                result[key] = shape[key]((raw as Record<string, unknown>)[key])
            } catch (error) {
                throw new TypeError(`${key}: ${(error as Error).message}`)
            }
        }
        return result as { [K in keyof S]: ReturnType<S[K]> }
    }
}

const parseUser = obj({ id: num, name: str, tags: arr(str) })
type User = ReturnType<typeof parseUser>        // { id: number; name: string; tags: string[] }

